style.css:
@-moz-document domain("youtube.com") {
:root {
    --my-bg: #0c0e13;
    --my-glass: rgba(30, 34, 43, 0.66);
    --my-glass-hover: rgba(57, 64, 77, 0.76);
    --my-border: rgba(255,255,255,0.16);
    --my-highlight: rgba(255,255,255,0.35);
    --my-shadow: 0 12px 40px rgba(0,0,0,.32);
}

/* Fond */
ytd-app,
#content,
ytd-rich-grid-renderer {
    background: var(--my-bg) !important;
}

/* Surfaces en verre */
ytd-masthead,
ytd-guide-renderer,
ytd-mini-guide-renderer,
ytd-searchbox,
yt-chip-cloud-chip-renderer,
ytd-menu-popup-renderer,
ytd-multi-page-menu-renderer,
tp-yt-paper-dialog {
    background: var(--my-glass) !important;
    border: 1px solid var(--my-border) !important;
    border-radius: 20px !important;
    -webkit-backdrop-filter: blur(14px) saturate(180%) !important;
    backdrop-filter: blur(14px) saturate(180%) !important;
    box-shadow:
        inset 0 1px 0 var(--my-highlight),
        inset 0 -1px 0 rgba(255,255,255,.04),
        var(--my-shadow) !important;
}

/* Barre supérieure */
ytd-masthead {
    border-radius: 0 0 22px 22px !important;
}

ytd-masthead #background {
    background: transparent !important;
}

/* Recherche */
ytd-searchbox {
    border-radius: 999px !important;
    overflow: hidden;
}

/* Catégories */
yt-chip-cloud-chip-renderer {
    border-radius: 999px !important;
    margin: 4px !important;
    transition: transform 250ms ease, background 250ms ease !important;
}

yt-chip-cloud-chip-renderer:hover {
    transform: translateY(-2px) scale(1.025);
    background: var(--my-glass-hover) !important;
    box-shadow: inset 0 1px 0 var(--my-highlight) !important;
}

/* Miniatures */
ytd-thumbnail {
    border-radius: 18px !important;
    overflow: hidden !important;
}

ytd-rich-item-renderer,
ytd-video-renderer,
ytd-grid-video-renderer {
    border-radius: 20px !important;
    transition: transform 280ms ease !important;
}

ytd-rich-item-renderer:hover,
ytd-video-renderer:hover,
ytd-grid-video-renderer:hover {
    transform: translateY(-3px);
}

/* Menus */
ytd-menu-popup-renderer,
ytd-multi-page-menu-renderer,
tp-yt-paper-dialog {
    border-radius: 22px !important;
    overflow: hidden !important;
}

/* Boutons */
yt-icon-button,
yt-button-shape,
ytd-button-renderer {
    transition: opacity 220ms ease, transform 220ms ease !important;
}

yt-icon-button:hover {
    transform: scale(1.08);
}

/* Scrollbar */
::-webkit-scrollbar {
    width: 7px;
}

::-webkit-scrollbar-thumb {
    background: rgba(255,255,255,.19);
    border-radius: 20px;
}

::-webkit-scrollbar-thumb:hover {
    background: rgba(255,255,255,.35);
}
}
